// V102.220 — inhaled bronchodilators → pending Drug Codex drafts, NAMES ONLY.
//  · public/bronchodilator-seed.js (generated by scripts/build-bronchodilator-seed.cjs from the MED Library Adult Bronchodilator Device Guide, W. Phaenthong, M.D.,
//    GINA/GOLD 2026, CC BY-NC-SA 4.0): credit + licence present, generic names normalised, brands free of strengths / devices, no duplicates;
//  · the build's cleaning rules (cleanBrand / ingredient / transform) on sample rows;
//  · admin: the REAL dcaBronchPlan / dcaBronchDraft / dcaBronchImportOpen in Chromium — only generics absent from drug_codex become drafts, a published drug is
//    never written, a draft passes the drug_codex_drafts create rule (submittedBy = uid, status pending, genericName set), the credit rides in every draft.
const fs = require('node:fs'), assert = require('node:assert/strict');
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const seed = require('../public/bronchodilator-seed.js');
const build = require('./build-bronchodilator-seed.cjs');
const html = fs.readFileSync('public/admin.html', 'utf8').replace(/\r\n/g, '\n');
assert.ok(/<title>Nika Admin \(V102\.\d+\)<\/title>/.test(html));

// ---- the seed
assert.ok(/Warodom Phaenthong, M\.D\./.test(seed.credit) && /GINA \/ GOLD 2026/.test(seed.credit) && /CC BY-NC-SA 4\.0/.test(seed.credit) && seed.credit.includes('sirmarkthemighty-ctrl.github.io/Adult-Bronchodilator-Guide-App'), 'credit: author, basis, licence, link');
assert.ok(seed.drugs.length >= 30 && seed.sourceRows >= 100, `a real extract: ${seed.sourceRows} rows → ${seed.drugs.length} generics`);
const names = seed.drugs.map(d => d.genericName.toLowerCase());
assert.equal(new Set(names).size, names.length, 'one entry per generic');
assert.ok(seed.drugs.every(d => JSON.stringify(Object.keys(d)) === '["genericName","brandNames"]'), 'NAMES ONLY — nothing but genericName + brandNames');
assert.ok(!names.some(n => /albuterol|beclomethasone/.test(n)), 'generic names normalised (salbutamol, beclometasone)');
const bad = seed.drugs.flatMap(d => d.brandNames.filter(b => /\d|\b(mg|mcg|ml|hfa|mdi|dpi|inhaler|evohaler|turbuhaler|respimat|ellipta|nebules)\b/i.test(b)).map(b => d.genericName + ': ' + b));
assert.deepEqual(bad, [], 'no strengths / device words left in a brand');
const brands = seed.drugs.flatMap(d => d.brandNames.map(b => b.toLowerCase()));
assert.equal(new Set(brands).size, brands.length, 'no brand listed twice');
assert.ok(seed.drugs.find(d => d.genericName === 'Salbutamol').brandNames.includes('Ventolin') && seed.drugs.find(d => d.genericName === 'Budesonide/Formoterol').brandNames.includes('Symbicort'), 'spot checks');

// ---- the cleaning rules
const eq = (a, b, m) => assert.equal(a, b, m);
for (const [from, to] of [['Ventolin Evohaler 100 mcg', 'Ventolin'], ['Budecort-200 Inhaler', 'Budecort'], ['BudeForu Inhalation Powder (Nipro)', 'BudeForu'], ['Salda Inhale 1 mg/mL', 'Salda'], ['Berodual Nebules / Drops', 'Berodual'],
    ['Symbicort Forte Turbuhaler 320/9', 'Symbicort'], ['Meptin Air 10 mcg', 'Meptin Air'], ['Tropoair 18 mcg (LupinHaler)', 'Tropoair'], ['Buto-Asma 100 mcg', 'Buto-Asma'], ['AirDuo RespiClick 55/14', 'AirDuo'], ['Trimbow MDI 87/5/9', 'Trimbow']]) eq(build.cleanBrand(from), to, `cleanBrand(${from})`);
for (const [from, to] of [['Salbutamol (albuterol) 90 mcg', 'Salbutamol'], ['Formoterol (strength unknown)', 'Formoterol'], ['Fluticasone propionate 50 mcg', 'Fluticasone propionate'], ['Salbutamol 2.5 mg per 2.5 mL', 'Salbutamol'], ['Beclomethasone 40 mcg', 'Beclometasone'], ['Levalbuterol 45 mcg', 'Levosalbutamol'], ['Budesonide 0.25-1 mg', 'Budesonide']]) eq(build.ingredient(from), to, `ingredient(${from})`);
const t = build.transform([{ marketName: 'Combivent Respimat', substance: 'Albuterol 100 mcg / Ipratropium 20 mcg' }, { marketName: 'Combivent UDV', substance: 'Salbutamol 2.5 mg / Ipratropium 0.5 mg per 2.5 mL' }, { marketName: 'Salbutamol Nebules 2.5 mg', substance: 'Salbutamol 2.5 mg per 2.5 mL' }, { marketName: 'Ventolin Evohaler 100 mcg', substance: 'Salbutamol 100 mcg' }]);
assert.deepEqual(t, [{ genericName: 'Salbutamol', brandNames: ['Ventolin'] }, { genericName: 'Salbutamol/Ipratropium', brandNames: ['Combivent'] }], 'albuterol = salbutamol groups together; a "brand" equal to the generic is dropped');

// ---- the admin import, real functions
function grab(marker) {
    const i = html.indexOf(marker); assert.ok(i >= 0, marker);
    let d = 0, k = html.indexOf('{', html.indexOf(')', i));
    for (; k < html.length; k++) { if (html[k] === '{') d++; else if (html[k] === '}' && --d === 0) break; }
    return html.slice(i, k + 1);
}
const keysI = html.indexOf('const DCA_FIELD_KEYS = ['); const keysSrc = html.slice(keysI, html.indexOf('];', keysI) + 2);
const fns = [keysSrc, grab('function dcaBronchPlan('), grab('function dcaBronchDraft('), grab('function dcaBronchImportOpen(')].join('\n');
assert.ok(html.includes('onclick="dcaBronchImportOpen()"') && html.includes('bronchodilator-seed.js?v='), 'button + script tag wired');

(async () => {
    const browser = await chromium.launch();
    try {
        const page = await browser.newPage({ viewport: { width: 900, height: 800 } });
        await page.setContent('<meta charset="utf-8"><body></body>');
        await page.addScriptTag({ path: 'public/bronchodilator-seed.js' });
        const r = await page.evaluate(async fns => {
            const out = { sets: [], toasts: [] };
            window.escapeHtml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
            window.showToast = m => out.toasts.push(m);
            window.auth = { currentUser: { uid: 'ADMIN1' } };
            window.firebase = { firestore: { FieldValue: { serverTimestamp: () => 'TS' } } };
            window.db = { batch: () => { const ops = []; return { set: (ref, data) => ops.push({ col: ref.col, data }), commit: async () => { out.sets.push(...ops); } }; }, collection: col => ({ doc: () => ({ col }) }) };
            window.dcaState = { codex: [{ _id: 'P1', genericName: 'salbutamol', brandNames: ['Ventolin'] }, { _id: 'P2', genericName: 'Aclidinium', brandNames: ['Tudorza'] }], drafts: [{ genericName: 'Ciclesonide', importSource: 'bronchodilator-seed' }, { genericName: 'Olodaterol', importSource: undefined }] };
            const run = new Function(fns + '; return { dcaBronchPlan, dcaBronchDraft, dcaBronchImportOpen };')();
            window.__b = run;
            const plan = run.dcaBronchPlan();
            out.counts = plan.reduce((m, x) => (m[x.action] = (m[x.action] || 0) + 1, m), {});
            out.sal = plan.find(x => x.seed.genericName === 'Salbutamol'); out.salNew = out.sal.newBrands;
            out.acl = plan.find(x => x.seed.genericName === 'Aclidinium').action;
            out.cic = plan.find(x => x.seed.genericName === 'Ciclesonide').action; out.olo = plan.find(x => x.seed.genericName === 'Olodaterol').action;
            run.dcaBronchImportOpen();
            out.overlay = document.body.innerText;
            out.goText = document.querySelector('[data-act="go"]').textContent;
            document.querySelector('[data-act="go"]').click(); await new Promise(r => setTimeout(r, 50));
            out.overlayGone = !document.querySelector('[data-act="go"]');
            return out;
        }, fns);
        const total = seed.drugs.length;
        assert.equal(r.acl, 'same', 'a published drug whose brands are all present: nothing to do');
        assert.equal(r.sal.action, 'info', 'a published drug with new brands is information only (never written)');
        assert.ok(r.salNew.includes('Aerotamol') && !r.salNew.includes('Ventolin'), 'the info row lists only the brands the codex lacks');
        assert.equal(r.cic, 'pending', 'a generic with a pending import draft is skipped'); assert.equal(r.olo, 'create', 'a pending draft from someone else (no importSource) does not block it');
        assert.equal(r.counts.create, total - 3, 'every other generic is a new draft: ' + JSON.stringify(r.counts));
        assert.match(r.overlay, /Bronchodilator drafts — names only/); assert.match(r.overlay, /Warodom Phaenthong, M\.D\./, 'the credit is on the preview');
        assert.equal(r.goText, `Create ${total - 3} drafts`);
        assert.equal(r.sets.length, total - 3, 'one draft per new generic');
        assert.ok(r.sets.every(s => s.col === 'drug_codex_drafts'), 'ONLY drug_codex_drafts is written — drug_codex is never touched');
        const d = r.sets[0].data;
        assert.ok(d.status === 'pending' && d.submittedBy === 'ADMIN1' && typeof d.genericName === 'string' && d.genericName.length > 0, 'passes the drug_codex_drafts create rule');
        assert.ok(r.sets.every(s => /Warodom Phaenthong/.test(s.data.internNotes) && s.data.references.length === 1 && s.data.importSource === 'bronchodilator-seed' && s.data.dosing === '' && s.data.indication === ''), 'credit in internNotes + references, names only (dosing / indication empty)');
        assert.ok(!r.sets.some(s => ['Salbutamol', 'Aclidinium', 'Ciclesonide'].includes(s.data.genericName)), 'the published / pending ones are not written');
        assert.ok(r.overlayGone && r.toasts.some(t => /drafts created/.test(t)), 'done: overlay closes, toast');
        console.log(`PASS: bronchodilator drafts — ${seed.sourceRows} source rows → ${total} generics / ${seed.drugs.reduce((n, x) => n + x.brandNames.length, 0)} brands, names only, credited (CC BY-NC-SA 4.0); only new generics become pending drafts, published drugs untouched`);
    } finally { await browser.close(); }
})().catch(e => { console.error(e); process.exit(1); });
